% Prints a matrix array to the MatLab command window with rows = trial chunks and columns = trial position within each chunk
% Does not modify OutcomePools indices (safe for runtime use)
% This function pulls the types/outcomes of the trial sequence generated by UrnModel.m
function previewMat = PreviewTrialSequence(TrialSeq, OutcomePools, chunkSizes)

% --- Abbreviations
typeAbbrev = struct( ...                                % Creates a struct containing trial type abbreviations for use by the matrix
    'A','A', ...                                        % In the matrix, trial types will be abbreviated in the following manner
    'B','B', ...
    'C','C', ...
    'D','D', ...
    'Blank','Bl');

outcomeAbbrev = struct( ...                             % In the matrix, trial outcomes will be abbreviated in the following manner
    'Reward','R', ...
    'AirPuff_Pressurize','P', ...
    'ITI','O');

nTrials = numel(TrialSeq);                              % Defines nTrials as equal to the number of elements in the TrialSeq array
C = numel(chunkSizes);                                  % Defines "C" as the total number of chunks in the trial sequence

% --- Generate local copy of outcome pools
types = fieldnames(OutcomePools);                       % Defines types as a cell array of trial type names (the field names of OutcomePools)
previewIdx = struct();                                  % Generates an empty struct named previewIdx (will hold one outcome counter per trial type)
for i = 1:numel(types)                                  % Defines i as a loop variable that increases by 1 for each trial type
    previewIdx.(types{i}) = 1;                          % Creates a counter for each trial type, starting at 1 (the first outcome in that type's pool)
end

% --- Build flat preview list
flatPreview = cell(1, nTrials);                         % Pre-allocates flatPreview as an empty cell array with one cell per trial
                                                        % TrialSeq and OutcomePools are generated by UrnModel.m and passed into this  
                                                        % function by CueConditioning.m, which this script then uses for matrix generation
for t = 1:nTrials                                       % Defines t as a loop variable with unique number for trial in the trial sequence
    type = TrialSeq{t};                                 % 'type' will pull the trial type info from the TrialSeq vector for each trial t
    pool = OutcomePools.(type);                         % 'pool' will pull the outcome struct array for each trial type in the trial sequence

    outcome = pool.seq{previewIdx.(type)};              % 'outcome' pulls the next unused outcome from that trial type's pool 
    previewIdx.(type) = previewIdx.(type) + 1;          % Advances that trial type's counter, so its next trial reads the next outcome

    flatPreview{t} = [ ...                              % For each trial within the trial sequence (t), flatPreview is defined as a cell containing:
        typeAbbrev.(type), ...                          % The trial type of trial t
        outcomeAbbrev.(outcome) ];                      % And the outcome of trial t
end

% --- Reshape into chunk × trial matrix
previewMat = cell(C, max(chunkSizes));  % allocate      % previewMat is defined as an array matrix containing cells with type/outcome info for each trial
idx = 1;                                                % idx tracks position in flatPreview, starting at trial 1

for c = 1:C                                             % For each chunk 'c' in the trial sequence,
    for b = 1:chunkSizes(c)                             % And for each trial 'b' within the trial chunk:
        previewMat{c,b} = flatPreview{idx};             % Update each previewMat cell to contain type/outcome info for that trial
        idx = idx + 1;                                  % Repeat this indexing process for all trials in the sequence
    end
end

% --- Print chunks with colors/styles                   % Prints each chunk as a color-coded row in the command window
for c = 1:C                                             % For each chunk c (formatting adapted from the 'cprintf' package, MatLab File Exchange):
    fprintf('\nChunk %d:\n', c);                        % Prints a 'Chunk #:' label above each chunk
    for b = 1:chunkSizes(c)                             % For each trial b within chunk c:
        token = previewMat{c,b};                        % Pulls that trial's type/outcome code (Ex: 'AR', 'BlP')

        % --- Parse token ---
        type    = token(1:end-1);                       % Everything except the last character = trial type (Ex: 'A', 'Bl')
        outcome = token(end);                           % Last character = outcome ('R' = reward, 'P' = airpuff, 'O' = omission)

        % --- Map trial type to color ---
        switch type                                     % Assigns a text color to each trial type
            case 'A', color = 'Red';
            case 'B', color = 'Blue';
            case 'C', color = 'Green';
            case 'D', color = 'Cyan';
            case 'Bl', color = 'Magenta';  
            otherwise, color = 'Black';                 % Any unrecognized type prints in black
        end

        % --- Map outcome to style prefix ---
        switch outcome                                  % Assigns a text style to each outcome
            case 'R'   % Reward
                token = [token(1:end-1) '★'];           % Replaces the 'R' with a star
                styleStr = ['*' color];         % Bold + trial type color
            case 'P'   % Airpuff
                styleStr = ['_' color];       % Underline + trial type color
            otherwise, styleStr = color;                % Omission: plain text in trial type color
        end

        % --- Print token ---
        if exist('cprintf','file')                      % If the cprintf package is installed:
            cprintf(styleStr, '%s', token);             % Prints the token in its color/style
            fprintf(' ');                               % Space separator (not underlined)
        else                                            % If cprintf is not installed:
            fprintf('%-4s ', token);                    % Prints plain, unstyled text instead
        end
    end
    fprintf('\n');                                      % New line after each chunk
end

